import java.util.*;
import java.io.*;

public class TextProcessor {
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder inputTextBuilder = new StringBuilder();
        String line;

        // 全ての入力を読み取る
        while ((line = reader.readLine()) != null && !line.isEmpty()) {
            inputTextBuilder.append(line).append("\n");
        }
        String inputText = inputTextBuilder.toString();

        // フィルタリストを読み取る
        List<Map<String, String>> filters = new ArrayList<>();
        if ((line = reader.readLine()) != null && !line.isEmpty()) {
            BufferedReader filterReader = new BufferedReader(new StringReader(line));
            while ((line = filterReader.readLine()) != null && !line.isEmpty()) {
                // シンプルフィルタをデシリアライズ
                Map<String, String> filter = new HashMap<>();
                String[] filterParts = line.split(":", 2);
                if (filterParts.length == 2) {
                    filter.put("type", filterParts[0].trim());
                    filter.put("value", filterParts[1].trim());
                    filters.add(filter);
                }
            }
            filterReader.close();
        }

        // 入力テキストにフィルタを適用
        String filteredText = applyOutputFilters(inputText, filters);

        // 結果を標準出力に書き出す
        System.out.println(filteredText);
    }

    private static String applyOutputFilters(String text, List<Map<String, String>> filters) {
        for (Map<String, String> filter : filters) {
            String filterType = filter.get("type");
            String value = filter.get("value");
            if ("remove_prefix".equals(filterType) && text.startsWith(value)) {
                text = text.substring(value.length());
            } else if ("remove_suffix".equals(filterType) && text.endsWith(value)) {
                text = text.substring(0, text.length() - value.length());
            } else if ("replace".equals(filterType)) {
                String oldValue = filter.get("old");
                String newValue = filter.get("new");
                if (oldValue != null && newValue != null) {
                    text = text.replace(oldValue, newValue);
                }
            }
        }
        return text.trim();
    }
}
