def _parse_http_status(header_path: str) -> int | None:
    """The final HTTP status code from a curl ``-D`` header dump — the last status
    line, so a redirect chain (``-L``) reports the code that actually served the
    body. ``None`` if unparseable."""
    status = None
    try:
