```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <regex>
#include <sstream>

bool is_valid_http_status(const std::string &line, int &status_code) {
    std::regex status_regex(R"(HTTP/\d+\.\d+\s+(\d{3}))");
    std::smatch match;
    if (std::regex_search(line, match, status_regex) && match.size() > 1) {
        status_code = std::stoi(match[1].str());
        return true;
    }
    return false;
}

int main() {
    std::string line;
    std::string header_content;

    // 標準入力からすべての入力を受け取る
    while (std::getline(std::cin, line)) {
        header_content += line + "\n";
    }

    int last_status_code = 0;
    std::istringstream header_stream(header_content);
    std::string current_line;
    while (std::getline(header_stream, current_line)) {
        int status_code = 0;
        if (is_valid_http_status(current_line, status_code)) {
            last_status_code = status_code;
        }
    }

    // 最後に見つかったHTTPステータスコードを出力
    std::cout << last_status_code << std::endl;

    return 0;
}
```

この修正により、正規表現の定義が正しくなり、コンパイルエラーが解消されます。

