#include <iostream>
#include <string>
#include <thread>
#include <mutex>
#include <queue>
#include <condition_variable>
#include <functional>
#include <atomic>

// 作業キューと同期用のロック
std::mutex queue_mutex;
std::condition_variable condition;
std::queue<std::function<void()>> task_queue;
std::atomic<bool> stop_worker(false);

// ワーカースレッド関数
void worker_thread() {
    while (true) {
        std::function<void()> task;

        {
            std::unique_lock<std::mutex> lock(queue_mutex);
            condition.wait(lock, [] { return !task_queue.empty() || stop_worker; });

            if (stop_worker && task_queue.empty()) {
                return;
            }

            task = std::move(task_queue.front());
            task_queue.pop();
        }

        task();  // タスクを実行
    }
}

// 非同期ツール関数のラッパー
void async_tool(const std::function<void()>& tool_body) {
    {
        std::lock_guard<std::mutex> lock(queue_mutex);
        task_queue.push(tool_body);
    }
    condition.notify_one();
}

int main() {
    // ワーカースレッドを開始
    std::thread worker(worker_thread);

    // 標準入力から値を読み取る
    std::vector<std::string> inputs;
    std::string line;

    while (std::getline(std::cin, line) && !line.empty()) {
        inputs.push_back(line);
    }

    // 各入力行に対して非同期ツールを実行
    for (const auto& inp : inputs) {
        async_tool([inp]() {
            // ブロッキング操作をシミュレート（例:Resolve呼び出し）
            std::this_thread::sleep_for(std::chrono::seconds(1));
            std::cout << "Processed: " << inp << std::endl;
        });
    }

    // 入力をすべて処理した後,ワーカースレッドを停止
    {
        std::lock_guard<std::mutex> lock(queue_mutex);
        stop_worker = true;
    }
    condition.notify_one();

    // ワーカースレッドを終了
    if (worker.joinable()) {
        worker.join();
    }

    return 0;
}
