    let stdin = io::stdin();
    let mut expression = String::new();
    let mut dialect = String::new();

    for line in stdin.lock().lines() {
        let input = line.expect("Failed to read line from stdin");

        // Ossieオブジェクトの解析とパース可能なSQL式の抽出
        if let Some((expr, dlt)) = parse_ossie_expression(&input) {
